st item=event.target.closest('[data-telefonia-id]');if(!item||event.target.closest('.convocatoria-activation-toast-close'))return;\n  event.preventDefault();event.stopImmediatePropagation();\n  const destination=new URL(item.getAttribute('href'),window.location.href);\n  if(destination.origin!==window.location.origin)return;"]]},{"path":"public/javascript/recordatorios.js","pairs":[["                lista.map(function (recordatorio) {\n                    const url = escapar(urlRecordatorio(recordatorio));\n                    const etiqueta = etiquetaVisibleRecordatorio(recordatorio);\n                    const estadoVisual = estadoVisibleRecordatorio(recordatorio);\n                    return (\n                        '<a class=\"topbar-reminder-item\" '+(Number(recordatorio.telefonia_id)>0?'data-telefonia-id=\"'+Number(recordatorio.telefonia_id)+'\" ':'')+'href=\"' + url + '\">' +\n                            '<span class=\"topbar-reminder-icon\">' +\n                                '<i class=\"bi ' + escapar(recordatorio.icono || 'bi-bell') + '\"></i>' +\n                            '</span>' +\n                            '<span class=\"topbar-reminder-copy\">' +\n                                '<strong>' + escapar(recordatorio.nombre_entidad || 'Seguimiento') + '</strong>' +","                lista.map(function (recordatorio) {\n                    const url = escapar(urlRecordatorio(recordatorio));\n                    const etiqueta = etiquetaVisibleRecordatorio(recordatorio);\n                    const estadoVisual = estadoVisibleRecordatorio(recordatorio);\n                    return (\n                        '<a class=\"topbar-reminder-item' +\n                            (Number(recordatorio.telefonia_id)>0 && Number(recordatorio.leida||0)===0 ? ' is-unread' : '') +\n                            '\" '+(Number(recordatorio.telefonia_id)>0?'data-telefonia-id=\"'+Number(recordatorio.telefonia_id)+'\" ':'')+'href=\"' + url + '\">' +\n                            '<span class=\"topbar-reminder-icon\">' +\n                                '<i class=\"bi ' + escapar(recordatorio.icono || 'bi-bell') + '\"></i>' +\n                            '</span>' +\n                            '<span class=\"topbar-reminder-copy\">' +\n                                '<strong>' + escapar(recordatorio.nombre_entidad || 'Seguimiento') + '</strong>' +"]]}],"create":{"path":"prueba_telefonia/api/leer_todas_notificaciones_llamada.php","content":"<?php\n/** Marcar avisos telefónicos como leídos; sin cerrar tareas de negocio. */\ndeclare(strict_types=1);\nsession_start();\nheader('Content-Type: application/json; charset=utf-8');\nheader('Cache-Control: private, no-store');\nrequire_once dirname(__DIR__,2).'/app/helpers/PermissionHelper.php';\nrequire_once dirname(__DIR__,2).'/app/services/TelefoniaNotificacionService.php';\n$uid=(int)($_SESSION['usuario_id']??0);\n$allowed=tienePermiso('telefonia.usar') &&\n    (tienePermiso('telefonia.recibir') ||\n    ((int)($_SESSION['rol_id']??0)===3 && tienePermiso('telefonia.salientes')));\nif(!$uid||!$allowed){http_response_code(403);echo '{\"ok\":false}';exit;}\nif(($_SERVER['REQUEST_METHOD']??'')!=='POST'){http_response_code(405);echo '{\"ok\":false}';exit;}\nif(empty($_SESSION['csrf_token']) ||\n    !hash_equals((string)$_SESSION['csrf_token'],(string)($_POST['csrf_token']??''))){\n    http_response_code(403);echo '{\"ok\":false}';exit;\n}\nsession_write_close();\ntry{\n    (new TelefoniaNotificacionService())->leerTodas($uid);\n    echo '{\"ok\":true}';\n}catch(Throwable $e){\n    error_log('[telefono_notificaciones_leer_todas] '.get_class($e));\n    http_response_code(500);echo '{\"ok\":false}';\n}\n"},"smoke":"<?php\ndeclare(strict_types=1);\n// Contrato sin BD ni Zadarma para la unificación del centro telefónico.\n$root=dirname(__DIR__);\n$get=static fn(string $name):string=>(string)file_get_contents($root.'/'.$name);\n$check=static function(bool $yes,string $why):void {\n    if(!$yes)throw new RuntimeException('Notificaciones: '.$why);\n};\n$common=$get('app/services/TelefoniaNotificacionService.php');\n$sales=$get('app/services/TelefoniaNotificacionVentasService.php');\n$marketing=$get('app/controllers/ConvocatoriaNotificacionController.php');\n$view=$get('app/views/layout/topbar.php');\n$api=$get('prueba_telefonia/api/leer_todas_notificaciones_llamada.php');\n$frontend=$get('public/javascript/telefonia_notificaciones.js');\n$reminders=$get('public/javascript/recordatorios.js');\n$check(str_contains($common,'operativasActuales'),\n    'No conservar notificaciones basándose en historial antiguo');\n$check(str_contains($common,'$this->operativasActuales[$llave]=true'),\n    'Transferencia todavía pendiente debe existir en los hechos');\n$check(str_contains($common,\"devolucion='PENDIENTE'\") || str_contains($common,\"'PENDIENTE'\"),\n    'Devolución se retira al atenderse');\n$check(str_contains($common,\"'leida'=>(int)\"),\n    'No restablecer leído a cero cada vez que consulta la campana');\n$check(str_contains($sales,'isset($wanted[$r['),\n    'Venta solo conserva obligaciones aún presentes');\n$check(str_contains($sales,'pendiente_operativo'),\n    'Ventas distingue lectura de obligación');\n$check(str_contains($marketing,'pendiente_operativo'),\n    'Marketing conserva conteo de obligaciones no cerradas');\n$check(str_contains($view,'data-phone-notification-read-all'),\n    'Analista y Ventas disponen de lectura masiva telefónica');\n$check(str_contains($frontend,'csrf_token:root.dataset.phoneNotificationCsrf'),\n    'Se requiere token CSRF para marcar todas');\n$check(str_contains($api,'hash_equals(') && str_contains($api,'leerTodas($uid)'),\n    'Endpoint propio requiere CSRF y sólo marca leída');\n$check(!str_contains($api,'devolucion=') && !str_contains($api,'resultado='),\n    'Leer nunca escribe estados de negocio');\n$check(str_contains($reminders,'Number(recordatorio.leida||0)===0'),\n    'La campana general refleja leída sin ocultar obligación');\necho \"OK: lectura masiva de telefonía, obligaciones operativas visibles y permisos propios.\\n\";\n"}''')
def die(s):
    sys.stderr.write('CONFLICTO: '+s+'\n');sys.exit(2)
if len(sys.argv)<2 or sys.argv[1] not in ('--check','--apply','--restore'):
    sys.stderr.write('Uso: IMPE_CRM_PUBLIC=/public_html bash publicador --check|--apply|--restore [ruta_respaldo]\n');sys.exit(1)
op=sys.argv[1]
given=os.environ.get('IMPE_CRM_PUBLIC','')
if not given:die('Falta IMPE_CRM_PUBLIC')
root=Path(given).resolve()
if not (root/'index.php').is_file():die('La ruta no es la raiz del CRM')
backup_root=Path(os.environ.get('IMPE_CRM_BACKUPS',str(Path.home()/'impe-notificaciones-backups'))).resolve()
if backup_root==root or backup_root in root.parents or root in backup_root.parents:die('Respaldo debe estar fuera de public_html')
entries=SPEC['mods']+[SPEC['create']]
names=[x['path'] for x in entries]
if len(names)!=7 or len(set(names))!=7:die('Manifiesto de archivos inesperado')
def digest(raw):return hashlib.sha256(raw).hexdigest()
def where(name,existing=True):
    target=root/name
    if target.is_symlink() or root not in target.resolve().parents:
        die('Ruta insegura: '+name)
    if existing and not target.is_file():die('Archivo faltante: '+name)
    if not existing and target.exists() and not target.is_file():die('Archivo no regular: '+name)
    return target
def atomic(f,data,mode):
    fd,tmp=tempfile.mkstemp(prefix='.impe-avisos-',dir=str(f.parent))
    try:
        os.fchmod(fd,mode)
        with os.fdopen(fd,'wb') as stream:
            stream.write(data);stream.flush();os.fsync(stream.fileno())
        os.replace(tmp,str(f))
    finally:
        if os.path.exists(tmp):os.unlink(tmp)
def lint(p,data):
    suffix='.js' if p.endswith('.js') else '.php'
    cmd='node' if suffix=='.js' else 'php'
    if not shutil.which(cmd):
        if cmd=='node':
            print('AVISO: node no instalado; los JS se validan en GitHub Actions.')
            return
        die('PHP requerido para verificar sintaxis')
    fd,tmp=tempfile.mkstemp(suffix=suffix)
    try:
        with os.fdopen(fd,'wb') as stream:stream.write(data)
        args=[cmd,'--check' if suffix=='.js' else '-l',tmp]
        p=subprocess.run(args,stdout=subprocess.PIPE,stderr=subprocess.PIPE)
        if p.returncode:die('Sintaxis invalida: '+(p.stderr+p.stdout).decode('utf8','replace')[-650:])
    finally:
        if os.path.exists(tmp):os.unlink(tmp)
if op=='--restore':
    if len(sys.argv)!=3:die('Restauracion exige directorio exacto del respaldo')
    b=Path(sys.argv[2]).resolve()
    if backup_root not in b.parents or b.is_symlink():die('Respaldo fuera de la carpeta autorizada')
    meta=b/'manifest.json'
    if not meta.is_file():die('Manifiesto ausente')
    rows=json.loads(meta.read_text(encoding='utf8'))
    if sorted(x['path'] for x in rows)!=sorted(names):die('Respaldo de otra entrega')
    restore=[]
    for x in rows:
        f=where(x['path'],not x['created'])
        actual=f.read_bytes() if f.exists() else None
        saved=b/x['backup']
        if not x['created']:
            if not saved.is_file():die('Respaldo de archivo ausente')
            original=saved.read_bytes()
            if digest(original)!=x['old_sha']:die('Respaldo corrupto: '+x['path'])
        else:original=None
        if x['changed']:
            if actual is None or digest(actual)!=x['new_sha']:
                die('Cambio posterior a la publicacion: '+x['path'])
        restore.append((f,original,x))
    for f,original,x in restore:
        if not x['changed']:continue
        if x['created']:f.unlink()
        else:atomic(f,original,x['mode'])
    print('OK: restauracion verificada de notificaciones; telefonia PBX intacta.')
    sys.exit(0)
if len(sys.argv)!=2:die('Argumentos inesperados')
plan=[]
for x in SPEC['mods']:
    f=where(x['path']);raw=f.read_bytes()
    if b'\r\n' in raw and raw.count(b'\r\n')!=raw.count(b'\n'):die('Finales de linea mixtos: '+x['path'])
    try:source=raw.decode('utf8').replace('\r\n','\n')
    except UnicodeDecodeError:die('No UTF-8: '+x['path'])
    changed=source;oldcount=newcount=0
    for old,new in x['pairs']:
        old=(old+'\n' if old.endswith('\r') else old).replace('\r\n','\n')
        new=(new+'\n' if new.endswith('\r') else new).replace('\r\n','\n')
        if source.count(old)==1 and source.count(new)==0:
            if changed.count(old)!=1:die('Parches solapados: '+x['path'])
            changed=changed.replace(old,new,1);oldcount+=1
        elif source.count(old)==0 and source.count(new)==1:newcount+=1
        else:die('Version personalizada no reconocida: '+x['path'])
    if oldcount and newcount:die('Parcialmente instalado: '+x['path'])
    result=(changed.replace('\n','\r\n') if b'\r\n' in raw else changed).encode('utf8')
    mode=stat.S_IMODE(f.stat().st_mode)
    plan.append(dict(path=x['path'],file=f,old=raw,new=result,
        created=False,changed=oldcount>0,mode=mode,state='pendiente' if oldcount else 'actualizado'))
x=SPEC['create'];f=where(x['path'],False)
raw=f.read_bytes() if f.exists() else None
new=x['content'].encode('utf8')
if raw is not None and raw!=new:die('Endpoint ya existe con contenido diferente: '+x['path'])
plan.append(dict(path=x['path'],file=f,old=raw,new=new,
    created=raw is None,changed=raw is None,
    mode=stat.S_IMODE(f.stat().st_mode) if f.exists() else 0o644,
    state='pendiente' if raw is None else 'actualizado'))
for x in plan:
    if x['changed']:lint(x['path'],x['new'])
# Prueba pura sobre los siete ficheros previstos, no sobre la BD real.
with tempfile.TemporaryDirectory(prefix='impe-notificaciones-test-') as tmp:
    scratch=Path(tmp)
    for x in plan:
        target=scratch/x['path'];target.parent.mkdir(parents=True,exist_ok=True)
        target.write_bytes(x['new'])
    test=scratch/'tests/telefonia_notificaciones_unificacion_smoke.php'
    test.parent.mkdir(parents=True,exist_ok=True)
    test.write_bytes(SPEC['smoke'].encode('utf8'))
    check=subprocess.run(['php',str(test)],stdout=subprocess.PIPE,stderr=subprocess.PIPE)
    if check.returncode:die('Regresion de notificaciones: '+(check.stdout+check.stderr).decode('utf8','replace')[-650:])
    print(check.stdout.decode('utf8','replace').strip())
for x in plan:print(x['path']+': '+x['state'])
pending=sum(1 for x in plan if x['changed'])
print('Archivos a modificar:',pending)
if op=='--check':
    print('OK: verificacion de solo lectura. No se aplicaron cambios.')
    sys.exit(0)
if not pending:
    print('OK: notificaciones unificadas ya instaladas.');sys.exit(0)
backup_root.mkdir(parents=True,exist_ok=True,mode=0o700)
os.chmod(str(backup_root),0o700)
b=Path(tempfile.mkdtemp(prefix='avisos-leidas-pendientes-',dir=str(backup_root)))
os.chmod(str(b),0o700)
rows=[]
for i,x in enumerate(plan):
    bk='%02d.bak'%i
    if x['old'] is not None:
        dst=b/bk;dst.write_bytes(x['old']);os.chmod(str(dst),0o600)
    rows.append(dict(path=x['path'],backup=bk,created=x['created'],changed=x['changed'],
        old_sha=digest(x['old']) if x['old'] is not None else '',
        new_sha=digest(x['new']),mode=x['mode']))
m=b/'manifest.json';m.write_text(json.dumps(rows,indent=2),encoding='utf8');os.chmod(str(m),0o600)
# Preflight de cambios concurrentes para los siete archivos antes de escribir.
for x in plan:
    actual=x['file'].read_bytes() if x['file'].exists() else None
    if actual!=x['old']:die('Archivo modificado durante validacion: '+x['path'])
modified=[]
try:
    for x in plan:
        if not x['changed']:continue
        atomic(x['file'],x['new'],x['mode'])
        modified.append(x)
except BaseException:
    for x in reversed(modified):
        current=x['file'].read_bytes() if x['file'].exists() else None
        if current is not None and digest(current)==digest(x['new']):
            if x['created']:x['file'].unlink()
            else:atomic(x['file'],x['old'],x['mode'])
    raise
print('OK: notificaciones unificadas publicadas. Respaldo:',str(b))
print('No se modifica BD, PBX, transferencias, audio ni formularios de resultado.')
